package com.hbm.client.missile.launchpad.large;
import com.hbm.missile.launchpad.large.*;import net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.EntityRenderersEvent;import net.neoforged.neoforge.client.extensions.common.*;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD) public final class LargeLaunchPadClient{@SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(LargeLaunchPadContent.ENTITY.get(),LargeLaunchPadRenderer::new);LargeLaunchPadBlockEntity.CLIENT_TICK=LargeLaunchPadEffects::tick;LargeLaunchPadBlockEntity.CLIENT_REMOVED=LargeLaunchPadEffects::removed;}@SubscribeEvent public static void extensions(RegisterClientExtensionsEvent event){event.registerItem(new IClientItemExtensions(){private LargeLaunchPadItemRenderer renderer;@Override public BlockEntityWithoutLevelRenderer getCustomRenderer(){if(renderer==null)renderer=new LargeLaunchPadItemRenderer();return renderer;}},LargeLaunchPadContent.ITEM.get());}private LargeLaunchPadClient(){}}
